	/**
	 * Compares the current gate to one child gate. The caller establishes that the operator preserves each child's row
	 * values (or, for joins and extensions, separately proves the crossed operand cannot overwrite them).
	 */
	private boolean transitionKeepsInputs(TupleExpr source, TupleExpr destination, QueryModelNode acquiredOwner) {
		// Test both changed edges before condition-read discharge. A local FILTER value says nothing about other
		// bindings that can change how the complete producer is invoked.
		QueryModelNode sourceChild = source;
		QueryModelNode sourceParent = source.getParentNode();
		if (sourceParent == condition.filter) {
			sourceChild = sourceParent;
			sourceParent = sourceParent.getParentNode();
		}
		TupleExpr producer = destination == condition.filter ? condition.filter.getArg() : destination;
		if (!preservesSourceProducerInput(sourceParent, sourceChild, source)
				|| !preservesDestinationProducerInput(source, destination, producer)) {
			return false;
		}
		if (!condition.reads.complete()) {
			return false;
		}
		ConditionVisibility before = visibility(source);
		ConditionVisibility after = visibility(destination);
		Set<String> inheritedReads = stableNames();
		inheritedReads.removeIf(name -> condition.localNonNull.test(condition.originalNode.apply(destination), name));
		if (inheritedReads.isEmpty()) {
			return true;
		}
		var beforeInput = before.argumentInput();
		var afterInput = after.argumentInput();
		if (!beforeInput.bindingDomainKnown() || !afterInput.bindingDomainKnown()
				|| !analysis.bindingFactsEquivalent(inheritedReads, beforeInput, afterInput)
				|| !beforeInput.sameScopeAs(afterInput) && !(source instanceof Union)) {
			return false;
		}
		for (String name : inheritedReads) {
			if (beforeInput.externalGuaranteedNames().contains(name) != afterInput.externalGuaranteedNames()
					.contains(name)
					|| !Objects.equals(beforeInput.externalValues().get(name), afterInput.externalValues().get(name))
					|| !sameOwners(before.owners(), after.owners(), name, acquiredOwner)) {
				return false;
			}
		}
		return true;
	}

	private boolean preservesSourceProducerInput(QueryModelNode parent, QueryModelNode child, TupleExpr source) {
		if (preservesProducerInput(parent, child, source)) {
			return true;
		}
		// Removing the original gate uses replacePreservingScope: its entry boundary is transferred to the
		// argument, or an unmarked forwarding layer is retained above a marked argument. The analyzer's detached
		// skeleton already models that transfer, so its inherited marker is not a newly introduced boundary.
		// A mapping-parameterized root can change join dispatch when exposed and still needs the ordinary proof.
		return condition.originalNode.apply(source) == condition.sourceArgument
				&& (condition.scopeChange || TupleExprs.isVariableScopeChange(condition.sourceArgument))
				&& !BindingScopePolicy.isMappingParameterizedOperator(condition.sourceArgument)
				&& condition.localNonNull instanceof PreparedFilterPlacementFacts facts
				&& facts.stableFilterExpression(condition.originalNode.apply(condition.expression));
	}

	private boolean preservesDestinationProducerInput(TupleExpr parent, TupleExpr destination, TupleExpr producer) {
		if (preservesProducerInput(parent, destination, producer)) {
			return true;
		}
		// A reverse move back to the original site wraps the very boundary transferred from the original FILTER.
		// The prepared wrapper propagates that boundary; it does not expose an atomic mapping invocation.
		return condition.scopeChange && condition.originalNode.apply(destination) == condition.sourceArgument
				&& !BindingScopePolicy.isMappingParameterizedOperator(condition.sourceArgument)
				&& condition.localNonNull instanceof PreparedFilterPlacementFacts facts
				&& facts.stableFilterExpression(condition.originalNode.apply(condition.expression));
	}

	private boolean preservesProducerInput(QueryModelNode parent, QueryModelNode child, TupleExpr producer) {
		if (BindingScopePolicy.filterWrapperPreservesProducerInput(parent, child, producer, false)) {
			return true;
		}
		if (condition.scopeChange || !(condition.localNonNull instanceof PreparedFilterPlacementFacts facts)
				|| !facts.cannotInjectIntoProducer(condition.originalNode.apply(producer))
				|| !facts.stableFilterExpression(condition.originalNode.apply(condition.expression))) {
			return false;
		}
		TupleExpr preceding = parent instanceof Join join && join.getRightArg() == child ? join.getLeftArg()
				: parent instanceof LeftJoin join && join.getRightArg() == child ? join.getLeftArg() : null;
		if (preceding == null) {
			return false;
		}
		QueryAlgebraBindingAnalysis.OutputFacts left = analysis.outputFacts(preceding, analysis.contextAt(preceding));
		// The injection proof short-circuits an empty candidate set; it cannot then establish which input route
		// the wrapper chooses. Unknown output domains likewise cannot prove equivalence.
		return left.possibleOutputsKnown() && !left.possibleOutputs().isEmpty()
				&& BindingScopePolicy.filterWrapperPreservesProducerInput(parent, child, producer, true);
	}

	private boolean sameOwners(List<BindingScopePolicy.FilterInputEdge> before,
			List<BindingScopePolicy.FilterInputEdge> after, String name, QueryModelNode acquiredOwner) {
		int first = 0;
		int second = 0;
		while (true) {
			while (first < before.size() && !before.get(first).names().contains(name)) {
				first++;
			}
			while (second < after.size() && (!after.get(second).names().contains(name)
					|| after.get(second).owner() == acquiredOwner)) {
				second++;
			}
			if (first == before.size() || second == after.size()) {
				return first == before.size() && second == after.size();
			}
			if (condition.originalNode.apply(before.get(first++).owner()) != condition.originalNode
					.apply(after.get(second++).owner())) {
				return false;
			}
		}
	}

	/** A relocated condition must retain each original owner that can still supply one of its reads. */
	boolean candidateKeepsConditionOwners(TupleExpr candidate) {
		if (condition.sourceOwners.isEmpty()) {
			return true;
		}
		return candidateKeepsConditionOwners(candidate, visibility(candidate));
	}

	private boolean candidateKeepsConditionOwners(TupleExpr candidate, ConditionVisibility visibility) {
		if (condition.sourceOwners.isEmpty()) {
			return true;
		}
		QueryModelNode originalCandidate = condition.originalNode.apply(candidate);
		boolean descendant = false;
		for (QueryModelNode current = originalCandidate; current != null; current = current.getParentNode()) {
			if (current == condition.sourceArgument) {
				descendant = true;
				break;
			}
		}
		// An assured output of a descendant shadows every owner on every row. An ancestor's assured names can
		// instead come from the crossed owner, so they do not establish the same condition input.
		Set<String> assured = descendant ? candidate.getAssuredBindingNames() : Set.of();
		List<BindingScopePolicy.FilterInputEdge> candidateOwners = visibility.owners();
		for (BindingScopePolicy.FilterInputEdge source : condition.sourceOwners) {
			for (String name : source.names()) {
				if (assured.contains(name)) {
					continue;
				}
				boolean retained = false;
				for (BindingScopePolicy.FilterInputEdge destination : candidateOwners) {
					if (condition.originalNode.apply(destination.owner()) == source.owner()
							&& destination.names().contains(name)) {
						retained = true;
						break;
					}
				}
				if (!retained) {
					return false;
				}
			}
		}
		return true;
	}

	/**
	 * Computes separate argument and condition frames for the unmarked gate used by a relocation. The source boundary
	 * stays on its old argument; the gate may borrow only the owners authorized by its prospective ancestry.
	 */
	private ConditionVisibility prospectiveVisibility(TupleExpr candidate) {
		if (candidate == condition.filter.getArg()) {
			return conditionVisibility(condition.filter, analysis, bindingNames);
		}
		return conditionVisibility(condition, candidate, analysis, bindingNames, false, current -> {
			QueryModelNode parent = current.getParentNode();
			if (parent == condition.filter) {
				return condition.scopeChange ? null
						: new BindingScopePolicy.FilterParent(condition.filter, condition.filter.getParentNode());
			}
			return new BindingScopePolicy.FilterParent(current, parent);
		});
	}

	/**
	 * Models the result bindings visible to a moved Filter after its argument has been evaluated. FilterIterator's
	 * projection can hide inherited rows even without a scope marker when the condition has an implicit subquery input
	 * that VarNameCollector does not report, such as a VALUES binding name.
	 */
	private QueryAlgebraBindingAnalysis.OutputFacts outputFactsVisibleToFilter(TupleExpr candidate,
			QueryAlgebraBindingAnalysis.ReadOnlyContext input) {
		QueryAlgebraBindingAnalysis.OutputFacts facts = analysis.outputFacts(candidate, input);
		return condition.retainsAllBindings(gateArgument, candidate, bindingNames) ? facts
				: facts.only(condition.retainedBindingNames(candidate, bindingNames));
	}

	/** The actual projection used by FilterIterator, including implicit VALUES correlation in EXISTS. */
	static ConditionVisibility conditionVisibility(Filter filter, QueryAlgebraBindingAnalysis analysis) {
		return conditionVisibility(filter, analysis, TupleExpr::getBindingNames);
	}

	/** {@link #conditionVisibility(Filter, QueryAlgebraBindingAnalysis)} with memoizable binding names. */
